  or g613 (n_364, sticky_bits, in_data[38]);
  or g614 (sticky_bits, n_354, n_355);
  or g615 (n_355, n_352, n_353);
  or g616 (n_353, in_data[4], n_349);
  or g617 (n_349, n_15, in_data[11]);
  or g618 (n_15, n_333, n_334);
  or g619 (n_354, n_350, n_351);
  or g620 (n_333, in_data[3], in_data[2]);
  or g621 (n_352, in_data[6], in_data[5]);
  or g622 (n_334, in_data[1], in_data[0]);
  or g623 (n_351, in_data[8], in_data[7]);
  or g624 (n_350, in_data[10], in_data[9]);
  or g625 (n_365, in_data[37], in_data[36]);
endmodule

module top_module(clk_pad, reset_pad, pcm_data_pad, mode_pad,
     data_out_pad);
  input clk_pad, reset_pad, pcm_data_pad, mode_pad;
  output [19:0] data_out_pad;
  wire clk_pad, reset_pad, pcm_data_pad, mode_pad;
  wire [19:0] data_out_pad;
  wire [25:0] cic_out;
  wire [49:0] cic_out_temp;
  wire [39:0] fir_temp;
  wire [22:0] fir_out;
  wire [19:0] data_out;
  wire UNCONNECTED291, clk, clk_a, clk_en, mode, pcm_data, reset;
  cic_filter CIC(clk, reset, pcm_data, mode, cic_out, clk_en,
       cic_out_temp);
  fir_filter FIR(clk, clk_en, reset, mode, cic_out, {fir_temp[39],
       UNCONNECTED291, fir_temp[37:0]});
  hb_filter HALFBAND(clk, clk_en, mode, reset, fir_out, data_out);
  scale_round_convergent_unfixed_to_23 scale({1'b0, fir_temp[39],
       fir_temp[37:0]}, fir_out);
  pc3c01 pc3c01_1(.CCLK (clk_a), .CP (clk));
  pc3d01 pc3d01_1(.PAD (clk_pad), .CIN (clk_a));
  pc3d01d pc3d01_2(.PAD (reset_pad), .CIN (reset));
  pc3d01 pc3d01_4(.PAD (mode_pad), .CIN (mode));
  pc3d01 pc3d01_5(.PAD (pcm_data_pad), .CIN (pcm_data));
  pc3o05 pc3o05_1(.I (data_out[0]), .PAD (data_out_pad[0]));
  pc3o05 pc3o05_2(.I (data_out[1]), .PAD (data_out_pad[1]));
  pc3o05 pc3o05_3(.I (data_out[2]), .PAD (data_out_pad[2]));
  pc3o05 pc3o05_4(.I (data_out[3]), .PAD (data_out_pad[3]));
  pc3o05 pc3o05_5(.I (data_out[4]), .PAD (data_out_pad[4]));
  pc3o05 pc3o05_6(.I (data_out[5]), .PAD (data_out_pad[5]));
  pc3o05 pc3o05_7(.I (data_out[6]), .PAD (data_out_pad[6]));
  pc3o05 pc3o05_8(.I (data_out[7]), .PAD (data_out_pad[7]));
  pc3o05 pc3o05_9(.I (data_out[8]), .PAD (data_out_pad[8]));
  pc3o05 pc3o05_10(.I (data_out[9]), .PAD (data_out_pad[9]));
  pc3o05 pc3o05_11(.I (data_out[10]), .PAD (data_out_pad[10]));
  pc3o05 pc3o05_12(.I (data_out[11]), .PAD (data_out_pad[11]));
  pc3o05 pc3o05_13(.I (data_out[12]), .PAD (data_out_pad[12]));
  pc3o05 pc3o05_14(.I (data_out[13]), .PAD (data_out_pad[13]));
  pc3o05 pc3o05_15(.I (data_out[14]), .PAD (data_out_pad[14]));
  pc3o05 pc3o05_16(.I (data_out[15]), .PAD (data_out_pad[15]));
  pc3o05 pc3o05_17(.I (data_out[16]), .PAD (data_out_pad[16]));
  pc3o05 pc3o05_18(.I (data_out[17]), .PAD (data_out_pad[17]));
